import{_ as t,o,c as a,a2 as i}from"./chunks/framework.76ZGnlPi.js";const p=JSON.parse('{"title":"Custom Booking Status & Confirmation","description":"","frontmatter":{},"headers":[],"relativePath":"customer/custom-booking-status/index.md","filePath":"customer/custom-booking-status/index.md"}'),s={name:"customer/custom-booking-status/index.md"};function n(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="custom-booking-status-confirmation" tabindex="-1">Custom Booking Status &amp; Confirmation <a class="header-anchor" href="#custom-booking-status-confirmation" aria-label="Permalink to &quot;Custom Booking Status &amp; Confirmation&quot;">​</a></h1><p>This guide covers the <strong>customer-facing</strong> view of a custom booking&#39;s lifecycle — what each status means, when you receive your ticket, and how to confirm receipt to close out the booking.</p><hr><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th><th>Auth</th></tr></thead><tbody><tr><td><strong>Confirm ticket received</strong> (legacy — see note below)</td><td><code>PATCH /api/v1/custom-booking/:id/confirm-received</code></td><td>Authenticated <strong>or</strong> guest (email + phone)</td></tr></tbody></table><blockquote><p><strong>What changed.</strong> Under the current flow, an admin uploads your ticket and records how many passengers it covers — that upload sends nothing and your ticket stays hidden from you while it awaits review. A <strong>second</strong> admin then reviews it; approving it is what opens your download and <strong>sends the ticket email</strong>. Our team closes the booking afterwards, and that step is internal and sends nothing. You no longer need to confirm receipt. The <code>PATCH .../confirm-received</code> endpoint is kept only for bookings that were already in <code>TICKET_RECEIVED</code> under the previous flow.</p></blockquote><blockquote><p><strong>Internal margin data is not exposed.</strong> Customer-facing responses (<code>GET /custom-booking/:id</code>, <code>GET /custom-booking</code>, and the create/update responses) <strong>never</strong> include <code>capitalPriceTotalSAR</code> or the entire <code>pricingSnapshot</code> object. <code>pricingSnapshot</code> (supplier fare, reducer, capital price, special-B2B FX levers, capital-price history) is returned <strong>only</strong> on the admin custom-booking endpoints. Do not build customer UI against it — use the top-level payable fields (<code>pricePerAdultSAR</code>, <code>totalPriceSAR</code> / <code>IDR</code> / <code>USD</code>) and <code>isSpecialB2B</code> instead.</p></blockquote><hr><h2 id="lifecycle-from-your-perspective" tabindex="-1">Lifecycle from Your Perspective <a class="header-anchor" href="#lifecycle-from-your-perspective" aria-label="Permalink to &quot;Lifecycle from Your Perspective&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means for you</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>We received your booking. Please submit your passenger list to move forward.</td></tr><tr><td><code>UPLOADED_MANIFEST</code></td><td>Your passenger list has been submitted. Normally a brief, transient state — your booking is confirmed automatically and moves to <code>CONFIRMED</code>. It only lingers here if the operator has turned off auto-confirm, in which case our team confirms it manually.</td></tr><tr><td><code>CONFIRMED</code></td><td>Your booking is confirmed and your invoice is issued. We email you a confirmation. To pay, <strong>choose a payment method</strong> via <code>POST /invoice/:id/generate-payment</code> — we then send you the matching instructions (Xendit link, or SAR/USD bank-transfer details) by <strong>WhatsApp</strong> (or email). You may cancel at this stage via <code>PATCH /custom-booking/:id/status</code>.</td></tr><tr><td><code>WAITING_FOR_PAYMENT</code></td><td>Your invoice is ready — please complete payment using the instructions we sent after you picked a payment method.</td></tr><tr><td><code>WAITING_PAYMENT_REVIEW</code></td><td><strong>Manual transfer only.</strong> We&#39;ve received your transfer proof and our team is verifying it. If approved, the booking moves to <code>PAID</code>. If we need a corrected proof, the booking returns to <code>WAITING_FOR_PAYMENT</code> so you can re-upload.</td></tr><tr><td><code>PAID</code></td><td><strong>Legacy only.</strong> Older bookings briefly showed this after payment. New bookings move straight to <code>WAITING_FOR_TICKET</code> once payment is received.</td></tr><tr><td><code>WAITING_FOR_TICKET</code></td><td>Payment received — the channel is preparing your ticket. New bookings reach this state automatically as soon as your payment settles. <strong>This is also what you see if a ticket has already arrived but our team hasn&#39;t finished checking it yet</strong> — see the next two rows.</td></tr><tr><td><code>TICKET_UPLOADED_FULL</code></td><td>Your tickets have arrived — every travelling passenger who needs one has a ticket on file. They are <strong>not</strong> available yet: a second admin has to review the upload first, and until that happens you keep seeing <code>WAITING_FOR_TICKET</code> instead of this status, with nothing to download. Once reviewed and released, the status updates, the file becomes downloadable, and we email it to you (see <a href="#ticket-email">Ticket Email</a>). A later, corrected upload on a booking that has already been released downloads immediately with no new email.</td></tr><tr><td><code>TICKET_UPLOADED_PARTIAL</code></td><td>The airline could only issue tickets for <strong>some</strong> of your passengers. Same review step as above: until a second admin releases the upload you see <code>WAITING_FOR_TICKET</code>, not this status, and there is nothing to download; once released, the tickets that did arrive become downloadable and we email them to you (see <a href="#ticket-email">Ticket Email</a>). The passengers we could not ticket are owed their money back, so the booking stays open while our team arranges that refund. The email tells you your ticket is ready; it does not say how many passengers it covers. Check the file, and our team contacts you directly about the refund.</td></tr><tr><td><code>SHORTFALL_REFUNDED</code></td><td>The money for the passengers we could not ticket has been sent back to you. Unlike the two rows above, you see this status as-is even before a second admin has released your ticket — <strong>but the download and the email still wait on that release</strong>, so <code>SHORTFALL_REFUNDED</code> alone does not mean the file is ready yet. The booking stays open until our team closes it, and no further email is sent automatically once you have been emailed. Once the refund is recorded the shortfall is settled, and the tickets we could not issue are not added to this booking afterwards — you have already been paid for them. Contact our team if you still need those seats.</td></tr><tr><td><code>TICKET_RECEIVED</code></td><td><strong>Legacy only.</strong> Older bookings that are still waiting for your receipt confirmation. New bookings never enter this state.</td></tr><tr><td><code>COMPLETED</code></td><td>Booking finalized — our team has verified your tickets and closed the booking. No email is sent at this point; you were emailed your tickets when they were released.</td></tr><tr><td><code>CANCELLED</code></td><td>Booking cancelled.</td></tr><tr><td><code>EXPIRED</code></td><td>Payment window elapsed before payment was received.</td></tr><tr><td><code>NOT_AVAILABLE</code></td><td>The channel could not provide seats for this booking.</td></tr></tbody></table><hr><h2 id="payment-instructions" tabindex="-1">Payment Instructions <a class="header-anchor" href="#payment-instructions" aria-label="Permalink to &quot;Payment Instructions&quot;">​</a></h2><p>When your booking reaches <code>CONFIRMED</code> (normally right after you submit your passenger list — see <a href="/ahlaan-train-docs/customer/custom-booking/#_4-update-passenger-manifest">auto-confirm</a>), we email you a confirmation. <strong>We do not send payment details yet</strong> — first you choose how you want to pay.</p><p>Call <code>POST /invoice/:id/generate-payment</code> with your chosen method (see <a href="/ahlaan-train-docs/customer/manual-transfer/">payment options</a> — pay in IDR via <strong>Xendit</strong>, or in <strong>SAR/USD</strong> via <strong>manual bank transfer</strong>). As soon as you do, we deliver the matching instructions to you:</p><ul><li><strong>Xendit</strong> — a hosted payment link.</li><li><strong>SAR / USD manual transfer</strong> — the destination bank account (bank name, account number, account holder) to transfer to, plus the exact amount.</li></ul><p>Either way, delivery prefers <strong>WhatsApp</strong> (to the contact phone on your booking) and falls back to <strong>email</strong> if there is no phone or the WhatsApp message can&#39;t be sent. The message includes your booking code, route, departure date, passenger count and the amount due.</p><p>Delivery is <strong>best-effort</strong> — if you don&#39;t receive the instructions within a few minutes, contact support with your booking code (re-sending the <em>same</em> method shortly after is de-duplicated, so it won&#39;t arrive twice; choosing a <em>different</em> method does send fresh instructions). You can also always retrieve the invoice/payment state via <code>GET /custom-booking/:id</code>, the available methods via <code>GET /invoice/:id/payment-options</code>, and — for a Xendit payment — the link itself on the <code>generate-payment</code> response.</p><hr><h2 id="ticket-email" tabindex="-1">Ticket Email <a class="header-anchor" href="#ticket-email" aria-label="Permalink to &quot;Ticket Email&quot;">​</a></h2><p>You receive this email <strong>once your ticket is released by a second admin</strong> — not when it is first uploaded, which sends nothing and leaves your ticket hidden. Release can happen from any status your ticket is delivered from — <code>TICKET_UPLOADED_FULL</code>, <code>TICKET_UPLOADED_PARTIAL</code>, <code>SHORTFALL_REFUNDED</code>, and also <code>TICKET_RECEIVED</code> or <code>COMPLETED</code> on an older booking that had its ticket uploaded after it was closed. Until release you keep seeing <code>WAITING_FOR_TICKET</code> on the first two (<code>SHORTFALL_REFUNDED</code> shows as itself either way, and a closed booking shows as closed). You do not wait for the booking to be closed — only for that release. The subject is:</p><blockquote><p><strong>Konfirmasi Tiket Kereta Anda - {bookingCode}</strong></p></blockquote><p>The email includes:</p><ul><li>Booking code, route, departure date, total price.</li><li>The passenger count, <strong>on a full delivery only</strong> — see below.</li><li>The ticket file as a downloadable attachment.</li></ul><p><strong>On a partial delivery</strong> the email does not state a passenger count and does not say your passenger data is complete, because at that point it is not. It tells you the ticket is issued and can be downloaded. It also does <strong>not</strong> mention the refund you are owed — our team contacts you about that separately.</p><p><strong>You are emailed once.</strong> If the remaining tickets arrive later, or a corrected file is uploaded, <strong>no new email is sent automatically</strong> — the booking page always has the current file, and support can trigger a manual resend on request.</p><p>The email is delivered asynchronously via our third-party provider and is <strong>not automatically retried</strong> by the queue worker — if you don&#39;t see it within a few minutes, check spam first, then contact support with your booking code and they can trigger a manual resend. See <a href="/ahlaan-train-docs/customer/tickets-email/">Tickets &amp; Email</a> for general email/ ticket-download guidance.</p><hr><h2 id="confirm-ticket-received-legacy" tabindex="-1">Confirm Ticket Received (legacy) <a class="header-anchor" href="#confirm-ticket-received-legacy" aria-label="Permalink to &quot;Confirm Ticket Received (legacy)&quot;">​</a></h2><blockquote><p><strong>Most customers can skip this section.</strong> It only applies to bookings that were left in <code>TICKET_RECEIVED</code> under the previous flow. New bookings are closed by our team after the uploaded ticket is verified.</p></blockquote><p>Once you&#39;ve received and verified your ticket, confirm receipt to move the booking to <code>COMPLETED</code>. The booking must currently be in <code>TICKET_RECEIVED</code>.</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATCH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /custom-booking/:id/confirm-received</span></span></code></pre></div><h3 id="authenticated-user" tabindex="-1">Authenticated user <a class="header-anchor" href="#authenticated-user" aria-label="Permalink to &quot;Authenticated user&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/v1/custom-booking/booking-123/confirm-received</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;jwt-token&gt;&quot;</span></span></code></pre></div><h3 id="guest-user" tabindex="-1">Guest user <a class="header-anchor" href="#guest-user" aria-label="Permalink to &quot;Guest user&quot;">​</a></h3><p>Guest access requires both <code>email</code> and <code>phone</code> query parameters matching the booking&#39;s <code>contactPerson</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PATCH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/api/v1/custom-booking/booking-123/confirm-received?email=guest@example.com&amp;phone=628123456789&#39;</span></span></code></pre></div><h3 id="response-200" tabindex="-1">Response (200) <a class="header-anchor" href="#response-200" aria-label="Permalink to &quot;Response (200)&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;booking-123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;bookingCode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ABC1234&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPLETED&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ticketChannel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0190abc1-...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HHR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h3><ul><li><code>400 Bad Request</code> — Booking is not in <code>TICKET_RECEIVED</code>.</li><li><code>401 Unauthorized</code> — Guest verification (email + phone) is required and missing.</li><li><code>403 Forbidden</code> — Authenticated user is not the booking owner.</li><li><code>404 Not Found</code> — Booking not found, or guest email/phone do not match.</li></ul><blockquote><p><strong>Note for admin callers.</strong> This route stays reachable with a real admin token — there is no admin equivalent to redirect to — but the response comes back with every money field removed: the six selling prices, <code>capitalPriceTotalSAR</code>, <code>pricingSnapshot</code>, and the whole <code>invoice</code> block. <code>invoiceId</code> and <code>exchangeRateId</code> still return. Booking money for an admin lives on <code>GET /api/v1/admin/custom-booking/:id</code>, which enforces <code>custom-bookings:read-pricing</code>. Customers, guests, and admins using an &quot;act as customer&quot; impersonation token are unaffected.</p><p><code>PATCH /custom-booking/:id/status</code> (cancel) behaves differently — it answers <code>403</code> to a real admin token and names <code>PATCH /api/v1/admin/custom-booking/:id/status</code> as the replacement. See <a href="/ahlaan-train-docs/customer/custom-booking/">Custom Booking</a>.</p></blockquote><hr><h2 id="auto-completion-legacy" tabindex="-1">Auto-Completion (legacy) <a class="header-anchor" href="#auto-completion-legacy" aria-label="Permalink to &quot;Auto-Completion (legacy)&quot;">​</a></h2><p>For bookings still in <code>TICKET_RECEIVED</code> under the legacy flow: if you don&#39;t confirm within 24 hours after the departure date, the system automatically transitions the booking <code>TICKET_RECEIVED → COMPLETED</code>. The booking response will include an <code>autoCompletedAt</code> timestamp in that case, instead of being null.</p><p>New bookings never reach <code>TICKET_RECEIVED</code> at all, so <code>autoCompletedAt</code> stays <code>null</code> and this cron does not apply to them. Uploading the ticket records how many passengers were ticketed and parks the booking at <code>TICKET_UPLOADED_FULL</code> or <code>TICKET_UPLOADED_PARTIAL</code>; our team closes it from there, and nothing transitions <em>into</em> <code>TICKET_RECEIVED</code> any more. The cron therefore only ever acts on bookings that predate that change.</p><p>You can still view the booking after auto-completion; no further customer action is required.</p><hr><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Limit</th><th>Window</th></tr></thead><tbody><tr><td><code>PATCH /custom-booking/:id/confirm-received</code></td><td>10</td><td>60s</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="/ahlaan-train-docs/customer/custom-manifest/">Custom Booking Manifests (Customer)</a> — upload your passenger manifest.</li><li><a href="/ahlaan-train-docs/customer/tickets-email/">Tickets &amp; Email</a> — ticket downloads and email resends.</li><li><a href="/ahlaan-train-docs/admin/custom-booking/">Custom Booking Management (Admin)</a> — admin-facing companion.</li></ul>`,52)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
